type ActionSeed = Pick<VendorActionLedgerEntry, "id" | "label" | "kind" | "disposition" | "authority" | "persistence" | "errorState" | "sourceAnchors" | "findings">;
function group(routes: readonly string[], capability: PortalCapability, sourceFiles: readonly string[], proofOwner: string, entries: readonly ActionSeed[]): VendorActionLedgerEntry[] {
  return entries.map(entry => ({ ...entry, routes, capability, sourceFiles, proofOwner }));
}

